/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        form = (document.clmSchdlNotiForm || { elements: [] });
        idInfoArr = new Array();
        loadTp = 'null';
        isOk = 'null';
        await scwin.checkSave();
        for (let i = 0; i < dlt_idInfoList.getRowCount(); i++) {
            idInfoArr[i] = new idInfo((String(((dlt_idInfoList.getCellData(i, "integ_usr_id") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].integ_usr_id"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "integ_usr_id") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].integ_usr_id"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_idInfoList.getCellData(i, "integ_usr_id") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].integ_usr_id"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "integ_usr_id") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].integ_usr_id"); })())))), (String(((dlt_idInfoList.getCellData(i, "corp_usr_nm") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].corp_usr_nm"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "corp_usr_nm") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].corp_usr_nm"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_idInfoList.getCellData(i, "corp_usr_nm") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].corp_usr_nm"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "corp_usr_nm") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].corp_usr_nm"); })())))), (String(((dlt_idInfoList.getCellData(i, "email") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].email"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "email") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].email"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_idInfoList.getCellData(i, "email") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].email"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "email") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].email"); })())))), (String(((dlt_idInfoList.getCellData(i, "tel_no") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].tel_no"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "tel_no") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].tel_no"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_idInfoList.getCellData(i, "tel_no") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].tel_no"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "tel_no") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].tel_no"); })())))));
        }
        $c.util.getComponent("ipt_userNm").setValue(idInfoArr[0].usr_nm);
        $c.util.getComponent("ipt_telNo").setValue(idInfoArr[0].tel_no);
        $c.util.getComponent("ipt_email").setValue(idInfoArr[0].email);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil50220.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_doAssgn();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @description input_29 을(를) 값을 넣는다 · input_33 을(를) 값을 넣는다 · input_37 을(를) 값을 넣는다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil50220.onpageload' });
    }
};


