///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_doAssgn
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_doAssgn = async function () {
    const sbmOptions = {
        id: "tx_doAssgn",
        method: "post",
        action: "/listInvstg/idAssgnPop.do",
        ref: "dma_doAssgnReq",
        target: "dlt_idInfoList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil50220.tx_doAssgn" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.checkSave
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkSave = async function () {
    /* sdd-asis-lifecycle:begin checkSave — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (loadTp === '1') {
        if (isOk !== 'true') {
            await $c.win.alert('오류발생');
        } else {
            await $c.win.alert('저장되었습니다.');
            (function () { const o = $c.win.getOpenerScope(); if (o) { $c.win.setPageFrameSrc($c.win.getFrame(o), null); } else { console.error('[sdd] 부모 창을 못 찾았다 — 새로고침하지 않는다(자기 화면을 다시 열면 무한 고리가 된다)'); } })();
            this.close();
        }
    }
    if (loadTp !== '0') {

    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setDataVars
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.setDataVars = function (ver) {
    /* sdd-asis-lifecycle:begin setDataVars — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    setLeadcomVars();
    setDates();
    if (ver === '1') {
        scwin.setDisable();
    } else {
        if (ver === '2' || ver === '3') {
            scwin.setFileDisable();
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setDisable
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setDisable = function () {
    /* sdd-asis-lifecycle:begin setDisable — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (let i = 0; i < form.length; i++) {
        form[i].disabled = true;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setFileDisable
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setFileDisable = function () {
    /* sdd-asis-lifecycle:begin setFileDisable — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const obj1 = form['attachFiles[0]'];
    const obj2 = form['attachFiles[1]'];
    obj1.disabled = true;
    obj2.disabled = true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.doAssgn
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.doAssgn = async function () {
    /* sdd-asis-lifecycle:begin doAssgn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    form.action = '/listInvstg/idAssgnPop.do';
    const comName = $c.util.getComponent('ipt_comNm').getValue();
    const usrId = $c.util.getComponent('slc_integUsrId').getValue();
    if (await scwin.checkValue()) {
        if (await $c.win.confirm('[' + comName + '] 회사를 ID [' + usrId + '] 에 배정 하시겠습니까?')) {
            await scwin.tx_doAssgn();
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkValue = async function () {
    /* sdd-asis-lifecycle:begin checkValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (($c.util.getComponent('ipt_isurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_isurCd').getValue())) === '') {
        await $c.win.alert('법인을 선택하십시오.');
        return false;
    } else {
        return true;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.doChangeChrg
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.doChangeChrg = async function () {
    /* sdd-asis-lifecycle:begin doChangeChrg — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await $c.win.confirm('선택한 담당자가 아닌 로그인한 담당자의 정보를 변경합니다.\r\n담당자정보 변경을 하시겠습니까?')) {
        $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil25100/jldfil25100.xml');
        this.close();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurCd corpRegNo bzRegNo comNm foundDd secugrp_id spot_isu_trd_mkt_tp_cd
 * @returns
 * @hidden N
*/
scwin.setCorpInfo = function (isurCd, corpRegNo, bzRegNo, comNm, foundDd, secugrp_id, spot_isu_trd_mkt_tp_cd) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("ipt_comNm").setValue(comNm);
    $c.util.getComponent("ipt_isurCd").setValue(isurCd);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setIdInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setIdInfo = function () {
    /* sdd-asis-lifecycle:begin setIdInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const idx = $c.util.getComponent('slc_integUsrId').getSelectedIndex();
    $c.util.getComponent("ipt_userNm").setValue(idInfoArr[idx].usr_nm);
    $c.util.getComponent("ipt_telNo").setValue(idInfoArr[idx].tel_no);
    $c.util.getComponent("ipt_email").setValue(idInfoArr[idx].email);
    /* sdd-asis-lifecycle:end */
};
